// Reminder 1: 'Lunch with Jordan tomorrow at 12:30' → 12:30 PM
// Reminder 2: 'Follow up with Maya if she's not there by 6:30 PM' → 6:30 PM (18:30)

const time1 = 12 * 60 + 30; // in minutes
const time2 = 18 * 60 + 30; // in minutes

const gapMinutes = time2 - time1;
const gapSeconds = gapMinutes * 60;

console.log('Reminder 1 time: 12:30 PM');
console.log('Reminder 2 time:  6:30 PM');
console.log('Time gap: ' + gapSeconds + ' seconds (' + (gapSeconds / 3600) + ' hours)');

const baseTimestamp = 1788269400.0;
const newTimestamp = baseTimestamp + gapSeconds;

console.log('');
console.log('Base timestamp: ' + baseTimestamp + ' → ' + new Date(baseTimestamp * 1000).toUTCString());
console.log('New timestamp:  ' + newTimestamp + ' → ' + new Date(newTimestamp * 1000).toUTCString());
"
